package org.local.donusturucu.qa;
import android.os.Bundle;import java.io.*;import java.lang.reflect.*;import org.json.*;
public class TextOnlyImages extends RichChains {
 public void onStart(){Bundle b=new Bundle();try{Class<?>type=Class.forName("org.local.donusturucu.DocumentEngine",true,getTargetContext().getClassLoader());Method read=type.getDeclaredMethod("read",File.class,String.class);read.setAccessible(true);File root=new File(getTargetContext().getExternalFilesDir(null),"text-only-images");root.mkdirs();JSONArray rows=new JSONArray();for(int repeat=1;repeat<=3;repeat++)for(String name:new String[]{"external.html","rel-external.epub","chain.html"}){JSONObject row=new JSONObject();row.put("case",name);row.put("repeat",repeat);try{File f=copy(name,root);String before=hash(f);String text=(String)read.invoke(null,f,name.endsWith("html")?"html":"epub");row.put("text",text);if(!text.contains("Merhaba")||text.indexOf((char)0xfffc)>=0)throw new IOException("Text/placeholder mismatch");if(!name.equals("external.html")&&(!text.contains("مرحبا بالعالم")||!text.contains("سلام دنیا")))throw new IOException("RTL text lost");if(!before.equals(hash(f)))throw new IOException("Original changed");row.put("source_unchanged",true);row.put("pass",true);}catch(Throwable e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer out=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");try{out.write(report.toString(2));}finally{out.close();}}b.putString("report",new File(root,"report.json").toString());finish(0,b);}catch(Throwable e){b.putString("error",e.toString());finish(1,b);}}
}
